INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO-001','beginner','Sprzęt i podzespoły / Hardware','Płyta główna i procesor','','description: Płyta łączy podzespoły, a procesor wykonuje obliczenia. Brak obrazu nie dowodzi awarii CPU. step: Zapisz kod POST lub sygnały dźwiękowe i sprawdź instrukcję dokładnego modelu.','','',''),
('beginner:ZERO-002','beginner','Sprzęt i podzespoły / Hardware','Pamięć RAM','','description: Niestabilność może wynikać z pamięci, gniazda albo ustawień. step: Po zabezpieczeniu danych uruchom test pamięci; przed wymianą sprawdź generację DDR.','','',''),
('beginner:ZERO-003','beginner','Dyski i dane / Storage & Data','Dyski SSD i HDD','','description: Znikający dysk może oznaczać awarię nośnika lub połączenia. step: Najpierw zrób kopię danych. Przy klikającym HDD przerwij próby.','','',''),
('beginner:ZERO-004','beginner','Obraz i ekran / Display','Karta graficzna','','description: Zakłócenia obrazu mogą wynikać z GPU, kabla, monitora lub sterownika. step: Porównaj inny kabel i monitor; zanotuj, kiedy pojawia się problem.','','',''),
('beginner:ZERO-005','beginner','Obraz i ekran / Display','Ekran laptopa','','description: Ciemny ekran, pęknięcie i migotanie przy ruchu pokrywy to różne objawy. step: Sprawdź jasność i obraz na zewnętrznym monitorze.','','',''),
('beginner:ZERO-006','beginner','Zasilanie / Power','Zasilacz komputera','','description: Brak zasilania może dotyczyć przewodu, gniazdka, zasilacza albo komputera. step: Sprawdź zewnętrzny przewód i gniazdko. Nigdy nie otwieraj zasilacza.','','',''),
('beginner:ZERO-007','beginner','Zasilanie / Power','Bateria i ładowanie','','description: Szybkie rozładowanie nie zawsze oznacza uszkodzony akumulator. step: Sprawdź raport baterii i zgodność ładowarki. Spuchniętej baterii nie ładuj.','','',''),
('beginner:ZERO-008','beginner','Chłodzenie / Cooling','Chłodzenie','','description: Kurz i zatkane wloty mogą powodować przegrzewanie. step: Odsłoń wloty i obserwuj temperatury; unikaj obciążania wyłączającego się sprzętu.','','',''),
('beginner:ZERO-009','beginner','Obraz i ekran / Display','Porty USB i HDMI','','description: Wygląd złącza nie gwarantuje obsługi obrazu lub konkretnej szybkości. step: Porównaj drugi kabel i sprawdź specyfikację portu.','','',''),
('beginner:ZERO-010','beginner','Peryferia / Peripherals','Klawiatura i touchpad','','description: Przyczyna może leżeć w ustawieniach, sprzęcie lub systemie. step: Sprawdź ustawienia i zewnętrzną klawiaturę; po zalaniu odłącz zasilanie.','','',''),
('beginner:ZERO-011','beginner','Sieć i internet / Network','Wi-Fi','','description: Połączenie z routerem nie oznacza dostępu do internetu. step: Sprawdź tę samą sieć na drugim urządzeniu.','','',''),
('beginner:ZERO-012','beginner','Peryferia / Peripherals','Dźwięk i mikrofon','','description: System może kierować dźwięk do innego urządzenia. step: Sprawdź wejście, wyjście i uprawnienia mikrofonu.','','',''),
('beginner:ZERO-013','beginner','BIOS i rozruch / BIOS & Boot','UEFI, BIOS i POST','','description: POST sprawdza sprzęt przed startem systemu. step: Zapisz komunikat i porównaj go z dokumentacją; nie zmieniaj wielu ustawień naraz.','','',''),
('beginner:ZERO-014','beginner','Serwis i diagnostyka / Service & Diagnostics','Obudowa i montaż','','description: Mocowania różnią się między modelami. step: Odłącz zasilanie i znajdź instrukcję serwisową; nie otwieraj obudowy na siłę.','','',''),
('beginner:ZERO-015','beginner','Serwis i diagnostyka / Service & Diagnostics','Przewody i taśmy','','description: Podobne wtyki nie muszą być zamienne. step: Sprawdź oznaczenia i nie ciągnij za przewód.','','',''),
('beginner:ZERO-016','beginner','Serwis i diagnostyka / Service & Diagnostics','Bluetooth','','description: Parowanie może blokować inne aktywne połączenie. step: Sprawdź tryb parowania i poziom baterii akcesorium.','','',''),
('beginner:ZERO-017','beginner','Sieć i internet / Network','Kamera internetowa','','description: Czarny obraz może oznaczać zamkniętą przesłonę lub brak uprawnień. step: Sprawdź przesłonę i działanie w drugiej aplikacji.','','',''),
('beginner:ZERO-018','beginner','System i sterowniki / System & Drivers','System operacyjny','','description: Kłopoty z uruchomieniem mogą dotyczyć oprogramowania albo dysku. step: Zapisz kod błędu; przed reinstalacją zabezpiecz pliki.','','',''),
('beginner:ZERO-019','beginner','Serwis i diagnostyka / Service & Diagnostics','Kopie zapasowe','','description: Kopia na tym samym dysku nie chroni przed jego awarią. step: Zapisz pliki na innym nośniku i sprawdź, czy kopię można otworzyć.','','',''),
('beginner:ZERO-020','beginner','Serwis i diagnostyka / Service & Diagnostics','Konserwacja','','description: Drożne wloty, aktualizacje i kopie ograniczają skutki awarii. step: Czyść obudowę po odłączeniu zasilania.','','',''),
('beginner:ZERO-021','beginner','Sprzęt i podzespoły / Hardware','Chipset i sekcja zasilania','','description: Układy płyty koordynują komunikację i zasilanie podzespołów. step: Odczytaj kody diagnostyczne; pomiary pod napięciem zostaw technikowi.','','',''),
('beginner:ZERO-022','beginner','Serwis i diagnostyka / Service & Diagnostics','Zegar RTC','','description: Powracająca utrata daty może wskazywać problem z podtrzymaniem zegara. step: Najpierw sprawdź synchronizację czasu.','','',''),
('beginner:ZERO-023','beginner','Chłodzenie / Cooling','Pasta termiczna i termopady','','description: Materiały termiczne przekazują ciepło do radiatora. step: Nie zastępuj termopadu pastą bez znajomości wymaganej grubości.','','',''),
('beginner:ZERO-024','beginner','System i sterowniki / System & Drivers','Sterowniki','','description: Błąd po aktualizacji nie musi oznaczać awarii sprzętu. step: Zapisz wersję sterownika; pobieraj go z oficjalnego źródła.','','',''),
('beginner:ZERO-025','beginner','Serwis i diagnostyka / Service & Diagnostics','Partycje i formatowanie','','description: Zmiana partycji może pozbawić dostępu do danych. step: Przed zmianami sprawdź kopię i właściwy nośnik.','','',''),
('beginner:ZERO-026','beginner','Dyski i dane / Storage & Data','Szyfrowanie i klucz odzyskiwania','','description: Po zmianach sprzętu zaszyfrowany dysk może poprosić o klucz. step: Znajdź własny klucz odzyskiwania przed reinstalacją.','','',''),
('beginner:ZERO-027','beginner','Sieć i internet / Network','Ethernet i router','','description: Brak połączenia może dotyczyć kabla, portu lub routera. step: Porównaj inny kabel i port.','','',''),
('beginner:ZERO-028','beginner','Peryferia / Peripherals','Drukarka','','description: Brak wydruku może wynikać z kolejki lub połączenia. step: Sprawdź zasilanie, kolejkę i połączenie.','','',''),
('beginner:ZERO-029','beginner','Peryferia / Peripherals','Stacja dokująca USB-C','','description: Działanie zależy od portu, przewodu i dostępnej mocy. step: Sprawdź specyfikację portu; nie każdy USB-C przesyła obraz.','','',''),
('beginner:ZERO-030','beginner','Dyski i dane / Storage & Data','Odzyskiwanie danych','','description: Zapisy na uszkodzonym dysku mogą utrudnić odzyskanie plików. step: Nie nadpisuj oryginału; przy ważnych danych zwróć się do specjalisty.','','',''),
('beginner:ZERO-031','beginner','Serwis i diagnostyka / Service & Diagnostics','Multimetr i woltomierz','','description: Błędny zakres lub gniazdo sondy stwarza zagrożenie. step: Poznaj instrukcję miernika; nie wykonuj pomiarów sieciowych bez kwalifikacji.','','',''),
('beginner:ZERO-032','beginner','Serwis i diagnostyka / Service & Diagnostics','Napięcia 3,3 V, 5 V i 12 V','','description: To nominalne linie zasilania komputerów stacjonarnych. step: Odczyt z programu nie dowodzi awarii; nie wkładaj sond do zasilacza.','','',''),
('beginner:ZERO-033','beginner','Zasilanie / Power','Napięcie zasilacza laptopa','','description: Zasilacze różnią się napięciem, mocą i wtykiem. step: Porównaj oznaczenia oryginału z dokumentacją modelu.','','',''),
('beginner:ZERO-034','beginner','Serwis i diagnostyka / Service & Diagnostics','Zwory i piny płyty głównej','','description: Położenie pinów zależy od konkretnej płyty. step: Identyfikuj piny wyłącznie według instrukcji modelu.','','',''),
('beginner:ZERO-035','beginner','Serwis i diagnostyka / Service & Diagnostics','Reset CMOS','','description: Reset UEFI może wpłynąć na rozruch i szyfrowanie. step: Zapisz ustawienia i znajdź klucz odzyskiwania przed zmianami.','','','');
